using System;using System.IO;using System.Collections;using System.Linq;using UnityEngine;using UnityEditor;using Unity.XR.CoreUtils;using UnityEngine.Rendering;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;
public class FlashlightChildProbe:MonoBehaviour{
 string folder;WatchDemoController w;Camera camera;int failures;RenderPipelineAsset previous;
 public static object Begin(string folder){EditorUtility.audioMasterMute=true;Directory.CreateDirectory(folder);var p=new GameObject("Child flashlight render probe").AddComponent<FlashlightChildProbe>();p.folder=folder;p.StartCoroutine(p.Go());return true;}
 void Check(bool ok,string text){File.AppendAllText(folder+"/checks.txt",(ok?"PASS ":"FAIL ")+text+"\n");if(!ok)failures++;}
 float Capture(string name,Renderer child){var rt=new RenderTexture(1100,850,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(1100,850,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1100,850),0,0);tex.Apply();File.WriteAllBytes(folder+"/"+name+".png",tex.EncodeToPNG());var centre=camera.WorldToScreenPoint(child.bounds.center);float sum=0;int count=0;for(int y=Mathf.Max(0,(int)centre.y-60);y<Mathf.Min(850,(int)centre.y+60);y+=2)for(int x=Mathf.Max(0,(int)centre.x-60);x<Mathf.Min(1100,(int)centre.x+60);x+=2){var c=tex.GetPixel(x,y);sum+=(c.r+c.g+c.b)/3;count++;}RenderTexture.active=null;camera.targetTexture=null;Destroy(tex);Destroy(rt);return sum/Mathf.Max(1,count);}
 IEnumerator Go(){
  w=FindAnyObjectByType<WatchDemoController>();var scene=w.GetComponent<NightmareScene>();var rig=FindAnyObjectByType<XROrigin>();foreach(var b in rig.GetComponentsInChildren<Behaviour>(true))if(b.GetType().Name.Contains("TrackedPose")||b.GetType().Name.Contains("InputModality"))b.enabled=false;
  HorrorTuning.Current.nightmareEnabled=true;Check(scene.Begin(true),"Nightmare scene starts");var cc=rig.GetComponent<CharacterController>();if(cc)cc.enabled=false;var eye=new Vector3(2.95f,8.2f,0);rig.MoveCameraToWorldLocation(eye);rig.Camera.transform.LookAt(w.State.Scare.Body+Vector3.up*.8f);scene.enabled=false;yield return null;
  scene.enabled=true;yield return null;var child=GameObject.Find("Nightmare child").GetComponent<Renderer>();var flash=FindObjectsByType<WatchLantern>(FindObjectsSortMode.None).First(x=>x.Slot==0);flash.transform.SetPositionAndRotation(eye+new Vector3(.15f,-.22f,0),Quaternion.LookRotation(child.bounds.center-(eye+new Vector3(.15f,-.22f,0))));w.State.CycleLantern(0);yield return new WaitForSeconds(.3f);
  var lamp=flash.GetComponentInChildren<Light>(true);Check(lamp&&lamp.enabled,"Actual flashlight is on");Check(child.enabled,"Child renderer is visible and safely separated");
  camera=new GameObject("Render review camera").AddComponent<Camera>();camera.enabled=false;camera.fieldOfView=65;camera.nearClipPlane=.04f;camera.transform.SetPositionAndRotation(rig.Camera.transform.position,rig.Camera.transform.rotation);
  previous=QualitySettings.renderPipeline;var quest=AssetDatabase.LoadAssetAtPath<RenderPipelineAsset>("Assets/_LighthouseKeepers/Settings/RenderPipeline/QuestPipeline.asset");QualitySettings.renderPipeline=quest;yield return new WaitForSeconds(.5f);
  Check(GraphicsSettings.currentRenderPipeline==quest,"Rendered with Quest URP asset in Editor");lamp.enabled=false;float dark=Capture("flashlight-off",child);lamp.enabled=true;float lit=Capture("flashlight-on",child);
  File.AppendAllText(folder+"/checks.txt","Child crop average off="+dark.ToString("F4")+" on="+lit.ToString("F4")+"; lamp range="+lamp.range.ToString("F2")+" intensity="+lamp.intensity.ToString("F2")+"\n");Check(lit>dark+.01f,"Flashlight raises child brightness");
  var shader=Shader.Find("Lighthouse/S5 Drowned oilskin");var errors=ShaderUtil.GetShaderMessages(shader).Where(x=>x.severity.ToString()=="Error").ToArray();Check(shader&&shader.isSupported&&errors.Length==0,"Drowned shader supported without Editor compile errors: "+string.Join(";",errors.Select(x=>x.message)));
  QualitySettings.renderPipeline=previous;File.WriteAllText(folder+"/result.json","{\"passed\":"+(failures==0?"true":"false")+",\"failures\":"+failures+"}");Destroy(camera.gameObject);Destroy(gameObject);
 }
}
